import '../css/SignUp.css';
export default function SignUp(props) {
    function userSignUp(event) {
        event.preventDefault();
        var username = document.querySelector('.userName').value;
        var usermail = document.querySelector('.userEmail').value;
        var password = document.querySelector('.userPassword').value;
        var userInfo = {
            username: username,
            usermail: usermail,
            password: password
        };
        console.log(userInfo);
        try {
        const response = fetch(
          `http://localhost:8080/userSignup`,{
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(userInfo)
          }
        );

        response.then(async (res) => {
          if (!res.ok) {
            const msg = await res.text();
            throw new Error(msg);
          }

          return res.json();
        })
        .then((data) => {
          props.setUserDetails(data.userDetails);
          props.setIsLoggedIn(true);
          navigate('/');
        })
        .catch((error) => {
          alert(error.message);
        });
      } catch (error) {
        console.error("Error:", error);
      }
    }
    return (
        <div className="signUpContainer">
            <span className="signUpHeader">
                <h2>Welcome</h2>
                <p>Sign up for a new account</p>
            </span>
            <form className="signUpForm">
                <label className="signUpLabel">
                    Username
                    <input type="text" name="username" className="userName" placeholder="Enter your username" />
                </label>
                <br />
                <label className="signUpLabel">
                    Email
                    <input type="email" name="email" className="userEmail" placeholder="Enter your email" />
                </label>
                <br />
                <label className="signUpLabel">
                    Password
                    <input type="password" name="password" className="userPassword" placeholder="Enter your password" />
                </label>
                <br />
                <label className="signUpLabel">
                    Confirm Password
                    <input type="password" name="confirmPassword" className="userConfirmPassword" placeholder="Confirm your password" />
                </label>
                <br />
                <button className="signUpButton" type="submit" onClick={userSignUp}>Sign Up</button>
                <p>Already have an account? <a href="/login" className='loginLink'>Log in</a></p>
            </form>
        </div>
    )
}
